import { countCh                        } from '../src/string/strutil'; 
import { expect} from "chai"; 
describe('countCh', () => {

    // Count occurrences of a character in a string
    it('should return the correct count of character occurrences in a string', () => {
      const data = "hello world";
      const char = "o";
      const result = countCh(data, char);
      expect(result).toBe(2);
    });

    // Handle empty string input
    it('should return 0 when the input string is empty', () => {
      const data = "";
      const char = "a";
      const result = countCh(data, char);
      expect(result).toBe(0);
    });

    // Return correct indices of character occurrences in an array
    it('should return the correct count of character occurrences in an array when character exists', () => {
        const data = "hello world";
        const char = "o";
        const arr = new Array(data.length);

        const result = countCh(data, char, arr);
        expect(result).toBe(2);
        expect(arr.slice(0, result)).toEqual([4, 7]);
    });

    it('should return the correct count of character occurrences in an array when character exists', () => {
        const data = "hello world";
        const char = "o";
        const arr = new Array(data.length);
        const start = 0;
        const end = data.length;
        const result = countCh(data, char, arr, start, end);
        expect(result).toBe(2);
        expect(arr.slice(0, result)).toEqual([4, 7]);
    });
});
